    do {
      let activeApi = try resolveApi()
      var reader = MessagesPigeonInteropReader(pigeonVar_args)
      reader.readListHeader()
      let allowListArg = reader.read([String]?.self)
      let optionsArg = reader.read(SharedPreferencesPigeonOptions.self)
      let res: [String: Any] = try activeApi.getAll(allowList: allowListArg, options: optionsArg)
      return MessagesPigeonInteropCodec.encode { $0.writeMap(res) }
    } catch let error as PigeonError {
      wrappedError.code = error.code
      wrappedError.message = error.message
      wrappedError.details = error.details
    } catch let error {
      wrappedError.code = "\(error)"
      wrappedError.message = "\(Swift.type(of: error))"
      wrappedError.details = "Stacktrace: \(Thread.callStackSymbols)"
    }
    return nil
  }
  /// Gets individual value stored with [key], if any.
  // swift-format-ignore: AlwaysUseLowerCamelCase
  @objc func getValue(key keyArg: NSString, pigeonVar_args: NSData, wrappedError: PigeonError)
    -> NSData?
  {
    do {
      let activeApi = try resolveApi()
      var reader = MessagesPigeonInteropReader(pigeonVar_args)
      reader.readListHeader()
      let optionsArg = reader.read(SharedPreferencesPigeonOptions.self)
      let res: Any? = try activeApi.getValue(key: keyArg as String, options: optionsArg)
      return MessagesPigeonInteropCodec.encodeOrNil(res)
    } catch let error as PigeonError {
      wrappedError.code = error.code
      wrappedError.message = error.message
      wrappedError.details = error.details
    } catch let error {
      wrappedError.code = "\(error)"
      wrappedError.message = "\(Swift.type(of: error))"
      wrappedError.details = "Stacktrace: \(Thread.callStackSymbols)"
    }
    return nil
  }
  /// Gets all properties from shared preferences data set with matching prefix.
  // swift-format-ignore: AlwaysUseLowerCamelCase
  @objc func getKeys(pigeonVar_args: NSData, wrappedError: PigeonError) -> NSData? {
    do {
      let activeApi = try resolveApi()
      var reader = MessagesPigeonInteropReader(pigeonVar_args)
      reader.readListHeader()
